-- =====================================================================
-- Power Utility Management System - 04_sample_data.sql   (Bangladesh, 17 Nov 2026)
-- Run after 03_functions_triggers_views.sql.  WARNING: deletes ALL customers, meters,
-- readings, bills, payments, requests and logins, then loads fresh sample data.
--
-- What is inside:
--   * Bangladesh tariffs (BERC order of June 2026, 5% VAT) used by calculate_bill_amount()
--   * 3 staff logins (password <staff password>): PUMSadmin, tech.john, billing.officer
--   * 200 sample customers built from the electricity survey (fake people: no real
--     respondent's name, phone, email or meter number is used). 100 men, 100 women,
--     all 8 divisions, all 6 distribution companies, homes, shops, factories and farms.
--     Their emails end in @example.com, so a test email (bill, code) never reaches a real person.
--   * 200 meters, 6 monthly readings each (1 Jun - 1 Nov 2026)
--   * bills CALCULATED from the readings by calculate_bill_amount() (never typed by hand)
--   * payments; the payment trigger sets each bill's status, then check_overdue_bills()
--     marks late bills Overdue
--   * service requests + comments from the problems people reported
--   * 7 demo customer logins (password customer123) - see the list at the end of this file
-- =====================================================================

-- The activity log (file 11) is switched off while the sample data loads, so it stays empty.
-- (If file 11 has not been run yet, this setting does nothing.)
SELECT set_config('app.skip_audit', 'on', false);

-- ---------------------------------------------------------------------
-- 1. Clear old data (children first). Tariffs are replaced in step 2.
-- ---------------------------------------------------------------------
TRUNCATE TABLE service_request_comments, service_requests, payments, bill_installments, bill_adjustments,
               bills, meter_reading_schedules, meter_readings, connections, customers, users CASCADE;

-- ---------------------------------------------------------------------
-- 2. Bangladesh tariffs (BERC retail tariff order, June 2026)
--    Residential (LT-A): 0-75 units Tk 5.26 | 76-200 Tk 8.50 | 201-300 Tk 9.10 |
--                        301-400 Tk 9.62 | 401-600 Tk 15.01 | above 600 Tk 17.35
--    Commercial (LT-E flat): Tk 15.36 per unit
--    Fixed charge = demand charge x a typical sanctioned load:
--       Residential Tk 42/kW  -> single phase 2 kW = Tk 84,  three phase 6 kW = Tk 252
--       Commercial  Tk 90/kW  -> single phase 3 kW = Tk 270, three phase 10 kW = Tk 900
--    VAT 5% on (fixed + energy charge)
-- ---------------------------------------------------------------------
DELETE FROM tariff_slabs;
DELETE FROM tariffs;

INSERT INTO tariffs (name, customer_type, connection_type, fixed_charge, tax_rate, effective_from, is_active) VALUES
('Residential LT-A Single Phase', 'Residential', 'Single Phase',  84.00, 5.00, '2026-06-01', TRUE),
('Residential LT-A Three Phase',  'Residential', 'Three Phase',  252.00, 5.00, '2026-06-01', TRUE),
('Commercial LT-E Single Phase',  'Commercial',  'Single Phase', 270.00, 5.00, '2026-06-01', TRUE),
('Commercial LT-E Three Phase',   'Commercial',  'Three Phase',  900.00, 5.00, '2026-06-01', TRUE);

-- the same residential slabs for single and three phase
INSERT INTO tariff_slabs (tariff_id, slab_order, start_unit, end_unit, rate_per_unit)
SELECT t.id, s.slab_order, s.start_unit, s.end_unit, s.rate_per_unit
FROM tariffs t
CROSS JOIN (VALUES (1, 0, 75, 5.26), (2, 76, 200, 8.50), (3, 201, 300, 9.10),
                   (4, 301, 400, 9.62), (5, 401, 600, 15.01), (6, 601, NULL, 17.35))
           AS s(slab_order, start_unit, end_unit, rate_per_unit)
WHERE t.customer_type = 'Residential';

-- commercial: one flat rate
INSERT INTO tariff_slabs (tariff_id, slab_order, start_unit, end_unit, rate_per_unit)
SELECT t.id, 1, 0, NULL, 15.36 FROM tariffs t WHERE t.customer_type = 'Commercial';

