-- Link the demo logins both ways (users.customer_id <-> customers.user_id)
UPDATE customers c SET user_id = u.id FROM users u
WHERE u.role = 'customer' AND u.email = c.email;
UPDATE users u SET customer_id = c.id FROM customers c
WHERE u.role = 'customer' AND c.user_id = u.id;

