-- ---------------------------------------------------------------------
-- 8. Bills: one per reading, CALCULATED with calculate_bill_amount()
--    period = previous reading date .. day before this reading, due 20 days after the reading.
--    15 meters keep their 1 Nov reading unbilled, so "Generate bill" has something to show.
-- ---------------------------------------------------------------------
WITH r AS (
    SELECT mr.id, mr.connection_id, mr.reading_date, (mr.current_reading - mr.previous_reading) AS units,
           LAG(mr.reading_date) OVER (PARTITION BY mr.connection_id ORDER BY mr.reading_date) AS prev_date,
           c.customer_type, co.connection_type, c.customer_number, co.meter_number
    FROM meter_readings mr
    JOIN connections co ON co.id = mr.connection_id
    JOIN customers c ON c.id = co.customer_id
),
todo AS (
    SELECT r.*, ROW_NUMBER() OVER (ORDER BY r.reading_date, r.customer_number) AS n
    FROM r
    WHERE NOT (r.reading_date = DATE '2026-11-01' AND r.meter_number IN (
'78144592', '6968506314', '16943046', '8657077716', '65751662', '6139462316', '68996362', '97866687', '1518570300', '2994435726', '4296791991', '22478263', '73786062', '38427417', '67060401'
))
)
INSERT INTO bills (bill_number, connection_id, billing_period_start, billing_period_end, due_date,
                   fixed_charge, variable_charge, tax_amount, total_amount, status, notes, created_at)
SELECT 'BILL-2026-' || LPAD(t.n::text, 4, '0'), t.connection_id,
       COALESCE(t.prev_date, (t.reading_date - INTERVAL '1 month')::date), t.reading_date - 1, t.reading_date + 20,
       a.fixed_charge, a.variable_charge, a.tax_amount, a.total_amount, 'Unpaid',
       to_char(t.reading_date - 1, 'Mon YYYY') || ' - ' || t.units || ' kWh',
       (t.reading_date + 2 + TIME '10:00') AT TIME ZONE 'Asia/Dhaka'
FROM todo t
CROSS JOIN LATERAL calculate_bill_amount(t.customer_type, t.connection_type, t.units) AS a
ORDER BY t.n;

