('048193737415', '2026-06-01', 1.0, 'Cash', '2026-05-05', NULL),
('048193737415', '2026-07-01', 1.0, 'Cash', '2026-06-08', NULL),
('048193737415', '2026-08-01', 1.0, 'Cash', '2026-07-13', NULL),
