('048193737415', '2026-10-01', 1.0, 'Cash', '2026-09-05', NULL),
('048193737415', '2026-11-01', 1.0, 'Cash', '2026-10-11', NULL)
),
plan AS (
    SELECT b.id AS bill_id, ROUND(b.total_amount * v.fraction, 2) AS amount, v.method, v.payment_date::date AS payment_date,
           v.reference, ROW_NUMBER() OVER (ORDER BY v.payment_date, b.bill_number) AS n
    FROM v
    JOIN connections co ON co.meter_number = v.meter_number
    JOIN bills b ON b.connection_id = co.id AND b.billing_period_end = v.reading_date::date - 1
)
INSERT INTO payments (payment_number, bill_id, amount, method, payment_date, reference, status, recorded_by, created_at)
SELECT 'PAY-2026-' || LPAD(plan.n::text, 4, '0'), plan.bill_id, plan.amount, plan.method, plan.payment_date, plan.reference,
       'Completed', (SELECT id FROM users WHERE username = 'billing.officer'),
       (plan.payment_date + TIME '12:00') AT TIME ZONE 'Asia/Dhaka'
FROM plan
ORDER BY plan.n;

-- late bills -> Overdue
SELECT check_overdue_bills();

